<body>

<a class="skip" href="#detail">Skip to selected notice</a>
<header class="header"><div class="brand"><span class="brand-mark" aria-hidden="true">CB</span><div><span class="eyebrow">Federal procurement workspace</span><h1>CanadaBuys desk</h1></div></div><div class="actions"><button id="refresh-workspace">Refresh</button><button id="receive-workspace" data-write>Receive workspace</button><button id="save-workspace">Save workspace</button><button id="open-import" class="primary" data-write>Import source</button></div></header>
<nav class="global-nav" aria-label="Workspace areas"><a class="button" href="/bidder-desk">Bidder desk</a><button data-mode="notices" aria-current="true">Notices</button><button data-mode="workshares" aria-current="false">Partner workshares</button><button data-mode="reports" aria-current="false">Reports</button><button data-mode="sources" aria-current="false">Sources &amp; handoffs</button></nav>
<div id="status" class="status" role="status" aria-live="polite">Opening the saved workspace…</div>
<section class="stats" aria-label="Workspace totals"><div class="stat"><strong id="stat-notices">—</strong><span>Retained notices</span></div><div class="stat"><strong id="stat-open">—</strong><span>In latest open feed</span></div><div class="stat"><strong id="stat-shortlist">—</strong><span>Shortlisted</span></div><div class="stat"><strong id="stat-workshares">—</strong><span>Partner workshares</span></div></section>
<main id="notices-view" class="workspace"><aside class="rail" aria-label="Tender notices"><div class="rail-controls"><label>Find a notice<input id="search" type="search" autocomplete="off" placeholder="Title, buyer, solicitation or text"></label><label>Sort<select id="sort"><option value="closing">Closing date</option><option value="updated">Latest update</option><option value="title">Title</option><option value="buyer">Buyer</option></select></label><div class="form-row"><label>Notice type<select id="type-filter"><option value="">All types</option></select></label><label>Review<select id="review-filter"><option value="">All dispositions</option></select></label></div><div class="form-row"><label>Closing window<select id="closing-filter"><option value="">All closing dates</option><option value="future">Still ahead</option><option value="7">Within 7 days</option><option value="30">Within 30 days</option><option value="past">Past</option><option value="unknown">Unspecified</option></select></label><label>Delivery region<select id="region-filter"><option value="">All regions</option></select></label></div><div class="row"><label class="check"><input id="shortlist-filter" type="checkbox">Shortlisted</label><label class="check"><input id="open-filter" type="checkbox">Latest open feed</label></div><span id="notice-count" class="muted small-text"></span></div><div class="selection-bar"><label class="check"><input id="select-page" type="checkbox">Select page</label><span id="selection-count">0 selected</span></div><ul id="notice-list" class="notice-list"></ul><div id="rail-empty" class="empty small-text" hidden></div><div id="pagination" class="selection-bar"></div></aside><section id="detail" class="detail" aria-label="Selected notice" tabindex="-1"></section></main>
<main id="global-view" class="global-panel" hidden></main>
<dialog id="import-dialog" aria-labelledby="import-title"><form id="import-form"><header class="dialog-header"><div><span class="eyebrow">Original CanadaBuys data</span><h2 id="import-title">Import a source edition</h2></div><button type="button" data-close="import-dialog" class="quiet">Close</button></header><div class="dialog-body"><p class="muted small-text">Choose the original CSV stream. Its complete bilingual rows and original file remain with the imported edition.</p><div class="form-row"><label>Stream<select id="import-stream"><option value="open-tenders">Open tenders</option><option value="new-tenders">New tenders</option><option value="complete-tenders">Complete tender history</option><option value="awards">Contract awards</option><option value="supply-arrangements">Standing offers and supply arrangements</option></select></label><label>Source label<input id="import-label" maxlength="300" placeholder="Publication or original filename"></label></div><label>Original URL<input id="import-url" type="url" placeholder="https://…"><span class="help">Retain the official download address with a manually selected file.</span></label><div class="form-row"><label>Retrieved at (UTC)<input id="import-retrieved" type="datetime-local" step="1"></label><label>Expected SHA-256, if supplied<input id="import-sha" class="mono" pattern="[a-fA-F0-9]{64}" maxlength="64" placeholder="Original published file digest"></label></div><div class="drop-zone" id="drop-zone"><p>Drop one complete CSV file here.</p><button type="button" id="choose-csv">Choose CSV file</button><input id="csv-file" type="file" accept=".csv,text/csv" class="sr-only"><span id="csv-info" class="file-info"></span></div><details><summary>Or paste CSV text</summary><label class="sr-only" for="import-text">Original CSV text</label><textarea id="import-text" class="mono" rows="10" spellcheck="false"></textarea></details><div id="import-error" class="error" role="alert" hidden></div></div><footer class="dialog-footer"><span id="import-progress" class="small-text muted"></span><div class="actions"><button type="button" data-close="import-dialog">Cancel</button><button type="submit" class="primary" id="submit-import" data-write>Retain and import</button></div></footer></form></dialog>
<dialog id="receive-dialog" aria-labelledby="receive-title"><form id="receive-form"><header class="dialog-header"><div><span class="eyebrow">Portable work and original sources</span><h2 id="receive-title">Receive a saved workspace</h2></div><button type="button" class="quiet" data-close="receive-dialog">Close</button></header><div class="dialog-body"><p class="muted small-text">Receive the original source editions, review decisions and partner workshares from a saved package. Review the returned handoff record for any local differences.</p><label>Workspace JSON file<input id="receive-file" type="file" accept=".json,application/json" required></label><div id="receive-info" class="file-info"></div><div id="receive-error" class="error" role="alert" hidden></div></div><footer class="dialog-footer"><span id="receive-progress" class="small-text muted"></span><div class="actions"><button type="button" data-close="receive-dialog">Cancel</button><button type="submit" class="primary" id="submit-receive" data-write>Receive workspace</button></div></footer></form></dialog>
<dialog id="record-dialog" aria-labelledby="record-title"><header class="dialog-header"><h2 id="record-title">Retained record</h2><button type="button" class="quiet" data-close="record-dialog">Close</button></header><div id="record-body" class="dialog-body"></div></dialog>

<script type="module">

const $ = id => document.getElementById(id);
const PAGE_SIZE=40;
const DISPOSITIONS=[['unreviewed','Unreviewed'],['reviewing','Reviewing'],['pursue','Pursue'],['passed','Passed']];
const WORKSHARE_STATES=[['draft','Draft'],['ready','Ready for review'],['partner-review','Partner review'],['agreed','Agreed'],['delivering','Delivering'],['completed','Completed'],['passed','Passed']];
const STREAMS=[['open-tenders','Open tenders'],['new-tenders','New tenders'],['complete-tenders','Complete tender history'],['awards','Contract awards'],['supply-arrangements','Standing offers and supply arrangements']];
const REQUIREMENT_STATES=[['unreviewed','Unreviewed'],['met','Met'],['gap','Gap to resolve'],['not-applicable','Not applicable']];
const state={data:null,mode:'notices',noticeId:null,entryId:null,tab:'notice',language:'en',page:1,search:'',sort:'closing',noticeType:'',disposition:'',closing:'',region:'',shortlistOnly:false,openOnly:false,selected:new Set(),details:new Map(),noticePending:new Map(),entryChoices:new Map(),sources:new Map(),receivings:new Map(),comparisons:new Map(),drafts:new Map(),requestToken:0,workspaceRequest:0,writing:false,sourceRaw:null,sourcePreview:null,sourceName:'',receivePackage:null,workshareId:null,workshareSearch:'',draftStorageWarning:false,loadedDraftWorkspace:null,sourcePage:1,handoffPage:1};
const clone=value=>JSON.parse(JSON.stringify(value));
function node(tag,attrs={},...children){const el=document.createElement(tag);for(const [key,value] of Object.entries(attrs)){if(value===undefined||value===null)continue;if(key==='class')el.className=value;else if(key.startsWith('on')&&typeof value==='function')el.addEventListener(key.slice(2),value);else if(['value','checked','disabled','hidden','selected','readOnly','indeterminate'].includes(key))el[key]=value;else el.setAttribute(key,value);}for(const child of children.flat(Infinity)){if(child===null||child===undefined||child===false)continue;el.append(child instanceof Node?child:document.createTextNode(String(child)));}return el;}
function text(value,fallback='—'){if(value===undefined||value===null||value==='')return fallback;return typeof value==='object'?JSON.stringify(value):String(value);}
function bilingual(value,language=state.language){if(value===null||value===undefined)return '';if(typeof value!=='object')return String(value);return String(value[language==='fr'?'fr':'en']||value[language==='fr'?'en':'fr']||'');}
function titleCase(value){return String(value||'').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/[_-]/g,' ').replace(/^./,x=>x.toUpperCase());}
function streamLabel(value){return STREAMS.find(([id])=>id===value)?.[1]||titleCase(value);}
function count(n,label){return Number(n).toLocaleString()+' '+label+(Number(n)===1?'':'s');}
function utcLabel(value){if(!value)return '—';if(/^\d{4}-\d{2}-\d{2}$/.test(value))return value;const d=new Date(value);return Number.isNaN(d.getTime())?String(value):d.toISOString().replace('T',' ').replace(/\.\d{3}Z$/,' UTC');}
function displayCents(value,currency='CAD'){if(!Number.isSafeInteger(value))return '—';const s=value<0?'-':'';const a=Math.abs(value);return s+(Math.floor(a/100)).toLocaleString()+'.'+String(a%100).padStart(2,'0')+' '+currency;}
function centsInput(value){if(!Number.isSafeInteger(value))return '';return (value<0?'-':'')+Math.floor(Math.abs(value)/100)+'.'+String(Math.abs(value)%100).padStart(2,'0');}
function parseCents(value,label){const s=String(value??'').trim();if(!/^\d+(?:\.\d{1,2})?$/.test(s))throw new Error(label+' must be a non-negative amount with at most two decimal places.');const [whole,fraction='']=s.split('.');const result=Number(whole)*100+Number(fraction.padEnd(2,'0'));if(!Number.isSafeInteger(result))throw new Error(label+' is outside the supported amount range.');return result;}
function safeURL(value){if(typeof value!=='string'||!value)return null;try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:null;}catch{return null;}}
function link(value,label){const url=safeURL(value);return url?node('a',{href:url,target:'_blank',rel:'noopener noreferrer'},label||value):node('span',{},text(label||value));}
function card(title,...children){return node('section',{class:'card'},title?node('h3',{},title):null,...children);}
function fieldRows(rows){return node('dl',{class:'fields'},...rows.map(([label,value,wide])=>node('div',{class:wide?'wide':undefined},node('dt',{},label),node('dd',{},value===undefined||value===null||value===''?'—':value))));}
function details(label,render){const d=node('details',{},node('summary',{},label));let loaded=false;d.addEventListener('toggle',()=>{if(d.open&&!loaded){loaded=true;d.append(render());}});return d;}
function rawDetails(label,value){return details(label,()=>node('pre',{class:'json'},JSON.stringify(value,null,2)));}
