 const record=state.forms.evidence,body={title:val('e-title'),kind:val('e-kind'),sourceUrl:val('e-url'),localOrigin:val('e-origin'),accessState:val('e-access'),language:val('e-language'),version:val('e-version'),issuedAt:val('e-issued')||null,pageOrSection:val('e-page'),supersedes:val('e-supersedes')||null,review:{state:val('e-review'),reviewedBy:val('e-reviewer'),reviewedAt:val('e-reviewed')||null,note:val('e-review-note')},relatedNoticeIdentifiers:lines(val('e-related')),accessFailure:val('e-failure'),notes:val('e-notes'),noticeId:record?record.noticeId:$('e-global').checked?null:state.notice?.id||null};
