 if(kind==='profile'){state.profile=profiles.find(p=>p.id===result.record.id);chooseOptions($('profile-select'),profiles,state.profile.id,'Create a company profile');}
 else {state.profile=profiles.find(p=>p.id===state.profile?.id)||profiles[0]||null;chooseOptions($('profile-select'),profiles,state.profile?.id,'Create a company profile');}
 if(state.notice){[state.requirements,state.decisions]=await Promise.all([all('requirement',state.notice.id),all('decision',state.notice.id)]);records('requirement',state.requirements);records('decision',state.decisions);}
 records('evidence',evidence.filter(e=>!e.noticeId||e.noticeId===state.notice?.id));await openRecord(kind,result.record.id);
