#!/usr/bin/env python3
"""Run the current canonical Library upload workflow in an explicit private state directory."""
from __future__ import annotations
import hashlib
import importlib.util
import json
import os
from pathlib import Path
import sys

HELPER_PATH = Path(os.environ.get("COMMONS_CANONICAL_LIBRARY_UPLOAD_HELPER",
    "/dev/shm/openalex-6ba15/library-helpers-20261011-2256/library_upload.py"))
HELPER_BYTES = 44876
HELPER_SHA256 = "5bc473dadefe1f68ee8797baaed19d6662642d0ea4bcba128fa12938faa0d767"

def main() -> int:
    if len(sys.argv) != 1 or sys.stdin.isatty():
        print("usage: library_upload_private_state.py < request.json", file=sys.stderr)
        return 2
    helper = HELPER_PATH.resolve(strict=True)
    raw = helper.read_bytes()
    if len(raw) != HELPER_BYTES or hashlib.sha256(raw).hexdigest() != HELPER_SHA256:
        raise RuntimeError("The retained canonical Library upload helper differs")
    selected = Path(os.environ.get("COMMONS_LIBRARY_UPLOAD_STATE_PARENT", str(Path.cwd() / "library-state")))
    if not selected.is_absolute():
        raise RuntimeError("The upload state directory must be absolute")
    selected.mkdir(parents=True, exist_ok=True, mode=0o700)
    if selected.is_symlink() or not selected.is_dir():
        raise RuntimeError("The selected upload state directory is not an original directory")
    spec = importlib.util.spec_from_file_location("commons_original_library_upload_5bc473", helper)
    if spec is None or spec.loader is None:
        raise RuntimeError("The canonical Library helper cannot be imported")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)

    class NativePrivateUploadWorkflow(module.LibraryUploadWorkflow):
        def _prepare(self, requests):
            prepared = []
            for batch in self._prepare_batches(requests):
                payloads = []
                for request in batch:
                    if request.purpose != "create_library_file" or request.is_shared:
                        raise RuntimeError("Only the original private artifact save is selected")
                    payload = dict(request.prepare_payload)
                    payload.pop("workspace_path", None)
                    payloads.append(payload)
                response = self.apps_client.call_tool(
                    module._LIBRARY_CONNECTOR_ID, "prepare_uploads", {"uploads": payloads})
                values = self._result_array(response, "uploads")
                if len(values) != len(batch):
                    raise RuntimeError("The canonical preparation count differs")
                for request, value in zip(batch, values, strict=True):
                    item = module.PreparedUpload.parse(request, value)
                    if item.transfer_mode != "upload_url":
                        raise RuntimeError("The original private source requires its returned upload URL")
                    prepared.append(item)
            return tuple(prepared), {}, frozenset()

    class NativeSignedUrlUploader(module.SignedUrlUploader):
        @staticmethod
        def _upload_one(executable, upload, state_directory, environment):
            return module.SignedUrlUploader._upload_one(
                executable, upload, state_directory,
                {**environment, "AZCOPY_CONCURRENCY_VALUE": "1"})

    try:
        request = json.load(sys.stdin)
        workflow = NativePrivateUploadWorkflow(
            apps_client=module.HostedAppsClient(),
            materializer=module.LibraryFileMaterializer(),
            uploader=NativeSignedUrlUploader(),
            state_parent=selected,
        )
        result = workflow.run(request)
        print(json.dumps(result, separators=(",", ":")), flush=True)
    except (module.HostedAppsError, module.LibraryFileTransferError, module.LibraryUploadError, OSError, json.JSONDecodeError, RuntimeError) as error:
        print(f"library upload failed: {error}", file=sys.stderr)
        return 1
    return 0

if __name__ == "__main__":
    raise SystemExit(main())

